#!/bin/sh
set -eu
# Authorized key is injected per test run (generated by the test, never committed).
printf '%s\n' "${AUTHORIZED_KEY:?AUTHORIZED_KEY required}" > /root/.ssh/authorized_keys
chmod 600 /root/.ssh/authorized_keys
ssh-keygen -A >/dev/null
cat > /etc/ssh/sshd_config <<CFG
Port 22
PermitRootLogin prohibit-password
PasswordAuthentication no
KbdInteractiveAuthentication no
PubkeyAuthentication yes
AllowTcpForwarding ${ALLOW_TCP_FORWARDING:-no}
X11Forwarding no
Subsystem sftp internal-sftp
CFG
# Optional: make an S3 endpoint reachable at the same 127.0.0.1:<port> the test process uses.
if [ -n "${S3_FORWARD_PORT:-}" ] && [ -n "${S3_FORWARD_TARGET:-}" ]; then
  socat TCP-LISTEN:"${S3_FORWARD_PORT}",bind=127.0.0.1,fork,reuseaddr TCP:"${S3_FORWARD_TARGET}" &
fi
# Seed sample data on targets.
if [ -n "${SEED_DATA:-}" ]; then
  mkdir -p /srv/data/sub
  printf 'orders,customers\n1,acme\n2,globex\n' > /srv/data/orders.csv
  head -c 3145728 /dev/urandom > /srv/data/sub/blob.bin
  printf 'unicode: Grüße 你好\n' > /srv/data/sub/notes.txt
fi
exec /usr/sbin/sshd -D -e
